TLM.f("Tempora/Quad6-5r",{"officium":"Feria Sexta in Passione et Morte Domini","rule":["Full text"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad5","Prelude","Passio","omit commemoratio incipit","no Ultima Evangelium"],"fallback":"Tempora/Quad6-0r","from":{"Introitus":"Tempora/Quad6-0r","Oratio":"Tempora/Quad6-0r","Lectio":"Tempora/Quad6-0r","Graduale":"Tempora/Quad6-0r","Evangelium":"Tempora/Quad6-0r","Offertorium":"Tempora/Quad6-0r","Secreta":"Tempora/Quad6-0r","Communio":"Tempora/Quad6-0r","Postcommunio":"Tempora/Quad6-0r","Munda Cor Passionis":"Tempora/Quad6-0r"},"sections":{"Introitus":[{"k":"ref","la":"Ps 21:20 et 22"},{"k":"text","la":"Dómine, ne longe fácias auxílium tuum a me, ad defensiónem meam áspice: líbera me de ore leónis, et a córnibus unicórnium humilitátem meam."},{"k":"ref","la":"Ps 21:2"},{"k":"text","la":"Deus, Deus meus, réspice in me: quare me dereliquísti? longe a salúte mea verba delictórum meórum."},{"k":"text","la":"Dómine, ne longe fácias auxílium tuum a me, ad defensiónem meam áspice: líbera me de ore leónis, et a córnibus unicórnium humilitátem meam."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui humáno géneri, ad imitándum humilitátis exémplum, Salvatórem nostrum carnem súmere et crucem subíre fecísti: concéde propítius; ut et patiéntiæ ipsíus habére documénta et resurrectiónis consórtia mereámur."},{"k":"macro","name":"Per eumdem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","la":"Phil 2:5-11"},{"k":"text","la":"Fratres: Hoc enim sentíte in vobis, quod et in Christo Jesu: qui, cum in forma Dei esset, non rapínam arbitrátus est esse se æquálem Deo: sed semetípsum exinanívit, formam servi accípiens, in similitúdinem hóminum factus, et hábitu invéntus ut homo. Humiliávit semetípsum, factus obédiens usque ad mortem, mortem autem crucis. Propter quod et Deus exaltávit illum: et donávit illi nomen, quod est super omne nomen: (hic genuflectitur) ut in nómine Jesu omne genu flectátur cœléstium, terréstrium et infernórum: et omnis lingua confiteátur, quia Dóminus Jesus Christus in glória est Dei Patris."}],"Graduale":[{"k":"ref","la":"Ps 72:24 et 1-3"},{"k":"text","la":"Tenuísti manum déxteram meam: et in voluntáte tua deduxísti me: et cum glória assumpsísti me."},{"k":"text","la":"Quam bonus Israël Deus rectis corde! mei autem pæne moti sunt pedes: pæne effúsi sunt gressus mei: quia zelávi in peccatóribus, pacem peccatórum videns.","mark":"V"},{"k":"sep"},{"k":"ref","la":"Tractus 21:2-9, 18, 19, 22, 24, 32"},{"k":"text","la":"Deus, Deus meus, réspice in me: quare me dereliquísti?"},{"k":"text","la":"Longe a salúte mea verba delictórum meórum.","mark":"V"},{"k":"text","la":"Deus meus, clamábo per diem, nec exáudies: in nocte, et non ad insipiéntiam mihi.","mark":"V"},{"k":"text","la":"Tu autem in sancto hábitas, laus Israël.","mark":"V"},{"k":"text","la":"In te speravérunt patres nostri: speravérunt, et liberásti eos.","mark":"V"},{"k":"text","la":"Ad te clamavérunt, et salvi facti sunt: in te speravérunt, et non sunt confúsi.","mark":"V"},{"k":"text","la":"Ego autem sum vermis, et non homo: oppróbrium hóminum et abjéctio plebis.","mark":"V"},{"k":"text","la":"Omnes, qui vidébant me, aspernabántur me: locúti sunt lábiis et movérunt caput.","mark":"V"},{"k":"text","la":"Sperávit in Dómino, erípiat eum: salvum fáciat eum, quóniam vult eum.","mark":"V"},{"k":"text","la":"Ipsi vero consideravérunt et conspexérunt me: divisérunt sibi vestiménta mea, et super vestem meam misérunt sortem.","mark":"V"},{"k":"text","la":"Líbera me de ore leónis: et a córnibus unicórnium humilitátem meam.","mark":"V"},{"k":"text","la":"Qui timétis Dóminum, laudáte eum: univérsum semen Jacob, magnificáte eum.","mark":"V"},{"k":"text","la":"Annuntiábitur Dómino generátio ventúra: et annuntiábunt cœli justítiam ejus.","mark":"V"},{"k":"text","la":"Pópulo, qui nascétur, quem fecit Dóminus.","mark":"V"}],"Evangelium":[{"k":"text","la":"v. Pássio Dómini nostri Jesu Christi secúndum Matthǽum"},{"k":"ref","la":"Matt 26:36-75; 27:1-60"},{"k":"text","la":"Tunc venit Jesus cum illis in villam, quæ dícitur Gethsémani, et dixit discípulis suis: J. Sedéte hic, donec vadam illuc et orem. C. Et assúmpto Petro et duóbus fíliis Zebedæi, cœpit contristári et mæstus esse. Tunc ait illis: J. Tristis est ánima mea usque ad mortem: sustinéte hic, et vigilate mecum. C. Et progréssus pusíllum, prócidit in fáciem suam, orans et dicens: J. Pater mi, si possíbile est, tránseat a me calix iste: Verúmtamen non sicut ego volo, sed sicut tu. C. Et venit ad discípulos suos, et invénit eos dormiéntes: et dicit Petro: J. Sic non potuístis una hora vigiláre mecum? Vigiláte et oráte, ut non intrétis in tentatiónem. Spíritus quidem promptus est, caro autem infírma. C. Iterum secúndo ábiit et orávit, dicens: J. Pater mi, si non potest hic calix transíre, nisi bibam illum, fiat volúntas tua. C. Et venit íterum, et invenit eos dormiéntes: erant enim óculi eórum graváti. Et relíctis illis, íterum ábiit et orávit tértio, eúndem sermónem dicens. Tunc venit ad discípulos suos, et dicit illis: J. Dormíte jam et requiéscite: ecce, appropinquávit hora, et Fílius hóminis tradétur in manus peccatórum. Súrgite, eámus: ecce, appropinquávit, qui me tradet. C. Adhuc eo loquénte, ecce, Judas, unus de duódecim, venit, et cum eo turba multa cum gládiis et fústibus, missi a princípibus sacerdótum et senióribus pópuli. Qui autem trádidit eum, dedit illis signum, dicens: S. Quemcúmque osculátus fúero, ipse est, tenéte eum. C. Et conféstim accédens ad Jesum, dixit: S. Ave, Rabbi. C. Et osculátus est eum. Dixítque illi Jesus: J. Amíce, ad quid venísti? C. Tunc accessérunt, et manus injecérunt in Jesum et tenuérunt eum. Et ecce, unus ex his, qui erant cum Jesu, exténdens manum, exémit gládium suum, et percútiens servum príncipis sacerdótum, amputávit aurículam ejus. Tunc ait illi Jesus: J. Convérte gládium tuum in locum suum. Omnes enim, qui accéperint gládium, gládio períbunt. An putas, quia non possum rogáre Patrem meum, et exhibébit mihi modo plus quam duódecim legiónes Angelórum? Quómodo ergo implebúntur Scripturæ, quia sic oportet fíeri? C. In illa hora dixit Jesus turbis: J. Tamquam ad latrónem exístis cum gládiis et fústibus comprehéndere me: cotídie apud vos sedébam docens in templo, et non me tenuístis. C. Hoc autem totum factum est, ut adimpleréntur Scripturæ Prophetárum. Tunc discípuli omnes, relícto eo, fugérunt. At illi tenéntes Jesum, duxérunt ad Cáipham, príncipem sacerdótum, ubi scribæ et senióres convénerant. Petrus autem sequebátur eum a longe, usque in átrium príncipis sacerdótum. Et ingréssus intro, sedébat cum minístris, ut vidéret finem. Príncipes autem sacerdótum et omne concílium quærébant falsum testimónium contra Jesum, ut eum morti tráderent: et non invenérunt, cum multi falsi testes accessíssent. Novíssime autem venérunt duo falsi testes et dixérunt: S. Hic dixit: Possum destrúere templum Dei, et post tríduum reædificáre illud. C. Et surgens princeps sacerdótum, ait illi: S. Nihil respóndes ad ea, quæ isti advérsum te testificántur? C. Jesus autem tacébat. Et princeps sacerdótum ait illi: S. Adjúro te per Deum vivum, ut dicas nobis, si tu es Christus, Fílius Dei. C. Dicit illi Jesus: J. Tu dixísti. Verúmtamen dico vobis, ámodo vidébitis Fílium hóminis sedéntem a dextris virtútis Dei, et veniéntem in núbibus cœli. C. Tunc princeps sacerdótum scidit vestiménta sua, dicens: S. Blasphemávit: quid adhuc egémus téstibus? Ecce, nunc audístis blasphémiam: quid vobis vidétur? C. At illi respondéntes dixérunt: S. Reus est mortis. C. Tunc exspuérunt in fáciem ejus, et cólaphis eum cecidérunt, álii autem palmas in fáciem ejus dedérunt, dicéntes: S. Prophetíza nobis, Christe, quis est, qui te percússit? C. Petrus vero sedébat foris in átrio: et accéssit ad eum una ancílla, dicens: S. Et tu cum Jesu Galilæo eras. C. At ille negávit coram ómnibus, dicens: S. Néscio, quid dicis. C. Exeúnte autem illo jánuam, vidit eum ália ancílla, et ait his, qui erant ibi: S. Et hic erat cum Jesu Nazaréno. C. Et íterum negávit cum juraménto: Quia non novi hóminem. Et post pusíllum accessérunt, qui stabant, et dixérunt Petro: S. Vere et tu ex illis es: nam et loquéla tua maniféstum te facit. C. Tunc cœpit detestári et juráre, quia non novísset hóminem. Et contínuo gallus cantávit. Et recordátus est Petrus verbi Jesu, quod díxerat: Priúsquam gallus cantet, ter me negábis. Et egréssus foras, flevit amáre. Mane autem facto, consílium iniérunt omnes príncipes sacerdótum et senióres pópuli advérsus Jesum, ut eum morti tráderent. Et vinctum adduxérunt eum, et tradidérunt Póntio Piláto præsidi. Tunc videns Judas, qui eum trádidit, quod damnátus esset, pæniténtia ductus, réttulit trigínta argénteos princípibus sacerdótum et senióribus, dicens: S. Peccávi, tradens sánguinem justum. C. At illi dixérunt: S. Quid ad nos? Tu vidéris. C. Et projéctis argénteis in templo, recéssit: et ábiens, láqueo se suspéndit. Príncipes autem sacerdótum, accéptis argénteis, dixérunt: S. Non licet eos míttere in córbonam: quia prétium sánguinis est. C. Consílio autem ínito, emérunt ex illis agrum fíguli, in sepultúram peregrinórum. Propter hoc vocátus est ager ille, Hacéldama, hoc est, ager sánguinis, usque in hodiérnum diem. Tunc implétum est, quod dictum est per Jeremíam Prophétam, dicéntem: Et accepérunt trigínta argénteos prétium appretiáti, quem appretiavérunt a fíliis Israël: et dedérunt eos in agrum fíguli, sicut constítuit mihi Dóminus. Jesus autem stetit ante præsidem, et interrogávit eum præses, dicens: S. Tu es Rex Judæórum? C. Dicit illi Jesus: J. Tu dicis. C. Et cum accusarétur a princípibus sacerdótum et senióribus, nihil respóndit. Tunc dicit illi Pilátus: S. Non audis, quanta advérsum te dicunt testimónia? C. Et non respóndit ei ad ullum verbum, ita ut mirarétur præses veheménter. Per diem autem sollémnem consuéverat præses pópulo dimíttere unum vinctum, quem voluíssent. Habébat autem tunc vinctum insígnem, qui dicebátur Barábbas. Congregátis ergo illis, dixit Pilátus: S. Quem vultis dimíttam vobis: Barábbam, an Jesum, qui dícitur Christus? C. Sciébat enim, quod per invídiam tradidíssent eum. Sedénte autem illo pro tribunáli, misit ad eum uxor ejus, dicens: S. Nihil tibi et justo illi: multa enim passa sum hódie per visum propter eum. C. Príncipes autem sacerdótum et senióres persuasérunt populis, ut péterent Barábbam, Jesum vero pérderent. Respóndens autem præses, ait illis: S. Quem vultis vobis de duóbus dimítti? C. At illi dixérunt: S. Barábbam. C. Dicit illis Pilátus: S. Quid ígitur fáciam de Jesu, qui dícitur Christus? C. Dicunt omnes: S. Crucifigátur. C. Ait illis præses: S. Quid enim mali fecit? C. At illi magis clamábant, dicéntes: S. Crucifigátur. C. Videns autem Pilátus, quia nihil profíceret, sed magis tumúltus fíeret: accépta aqua, lavit manus coram pópulo, dicens: S. Innocens ego sum a sánguine justi hujus: vos vidéritis. C. Et respóndens univérsus pópulus, dixit: S. Sanguis ejus super nos et super fílios nostros. C. Tunc dimísit illis Barábbam: Jesum autem flagellátum trádidit eis, ut crucifigerétur. Tunc mílites præsidis suscipiéntes Jesum in prætórium, congregavérunt ad eum univérsam cohórtem: et exuéntes eum, chlámydem coccíneam circumdedérunt ei: et plecténtes corónam de spinis, posuérunt super caput ejus, et arúndinem in déxtera ejus. Et genu flexo ante eum, illudébant ei, dicéntes: S. Ave, Rex Judæórum. C. Et exspuéntes in eum, accepérunt arúndinem, et percutiébant caput ejus. Et postquam illusérunt ei, exuérunt eum chlámyde et induérunt eum vestiméntis ejus, et duxérunt eum, ut crucifígerent. Exeúntes autem, invenérunt hóminem Cyrenæum, nómine Simónem: hunc angariavérunt, ut tólleret crucem ejus. Et venérunt in locum, qui dícitur Gólgotha, quod est Calváriæ locus. Et dedérunt ei vinum bíbere cum felle mixtum. Et cum gustásset, nóluit bibere. Postquam autem crucifixérunt eum, divisérunt vestiménta ejus, sortem mitténtes: ut implerétur, quod dictum est per Prophétam dicentem: Divisérunt sibi vestiménta mea, et super vestem meam misérunt sortem. Et sedéntes, servábant eum. Et imposuérunt super caput ejus causam ipsíus scriptam: Hic est Jesus, Rex Judæórum. Tunc crucifíxi sunt cum eo duo latrónes: unus a dextris et unus a sinístris. Prætereúntes autem blasphemábant eum, movéntes cápita sua et dicéntes: S. Vah, qui déstruis templum Dei et in tríduo illud reædíficas: salva temetípsum. Si Fílius Dei es, descénde de cruce. C. Simíliter et príncipes sacerdótum illudéntes cum scribis et senióribus, dicébant: S. Alios salvos fecit, seípsum non potest salvum fácere: si Rex Israël est, descéndat nunc de cruce, et crédimus ei: confídit in Deo: líberet nunc, si vult eum: dixit enim: Quia Fílius Dei sum. C. Idípsum autem et latrónes, qui crucifíxi erant cum eo, improperábant ei. A sexta autem hora ténebræ factæ sunt super univérsam terram usque ad horam nonam. Et circa horam nonam clamávit Jesus voce magna, dicens: J. Eli, Eli, lamma sabactháni? C. Hoc est: J. Deus meus, Deus meus, ut quid dereliquísti me? C. Quidam autem illic stantes et audiéntes dicébant: S. Elíam vocat iste. C. Et contínuo currens unus ex eis, accéptam spóngiam implévit acéto et impósuit arúndini, et dabat ei bíbere. Céteri vero dicébant: S. Sine, videámus, an véniat Elías líberans eum. C. Jesus autem íterum clamans voce magna, emísit spíritum."},{"k":"rubric","la":"Hic genuflectitur, et pausatur aliquantulum."},{"k":"text","la":"Et ecce, velum templi scissum est in duas partes a summo usque deórsum: et terra mota est, et petræ scissæ sunt, et monuménta apérta sunt: et multa córpora sanctórum, qui dormíerant, surrexérunt. Et exeúntes de monuméntis post resurrectiónem ejus, venérunt in sanctam civitátem, et apparuérunt multis. Centúrio autem et qui cum eo erant, custodiéntes Jesum, viso terræmótu et his, quæ fiébant, timuérunt valde, dicéntes: S. Vere Fílius Dei erat iste. C. Erant autem ibi mulíeres multæ a longe, quæ secútæ erant Jesum a Galilæa, ministrántes ei: inter quas erat María Magdaléne, et María Jacóbi, et Joseph mater, et mater filiórum Zebedæi. Cum autem sero factum esset, venit quidam homo dives ab Arimathæa, nómine Joseph, qui et ipse discípulus erat Jesu. Hic accéssit ad Pilátum, et pétiit corpus Jesu. Tunc Pilátus jussit reddi corpus. Et accépto córpore, Joseph invólvit illud in síndone munda. Et pósuit illud in monuménto suo novo, quod excíderat in petra. Et advólvit saxum magnum ad óstium monuménti, et ábiit."}],"Offertorium":[{"k":"ref","la":"Ps 68:21-22"},{"k":"text","la":"Impropérium exspectávit cor meum et misériam: et sustínui, qui simul mecum contristarétur, et non fuit: consolántem me quæsívi, et non invéni: et dedérunt in escam meam fel, et in siti mea potavérunt me acéto."}],"Secreta":[{"k":"text","la":"Concéde, quǽsumus, Dómine: ut óculis tuæ majestátis munus oblátum, et grátiam nobis devotiónis obtíneat, et efféctum beátæ perennitátis acquírat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 26:42"},{"k":"text","la":"Pater, si non potest hic calix transíre, nisi bibam illum: fiat volúntas tua."}],"Postcommunio":[{"k":"text","la":"Per hujus, Dómine, operatiónem mystérii: et vitia nostra purgéntur, et justa desidéria compleántur."},{"k":"macro","name":"Per Dominum"}],"Munda Cor Passionis":[{"k":"text","la":"Munda cor meum ac lábia mea, omnípotens Deus, qui lábia Isaíæ Prophétæ cálculo mundásti igníto: ita me tua grata miseratióne dignáre mundáre, ut sanctum Evangélium tuum digne váleam nuntiáre. Per Christum, Dóminum nostrum. Amen."},{"k":"text","la":"Jube, domne, benedícere.","mark":"D"},{"k":"text","la":"Dóminus sit in córdibus vestris et in lábiis vestris: ut digne et competénter annuntiétis Evangélium suum: In nómine Patris, et Fílii, + et Spíritus Sancti.","mark":"S"},{"k":"text","la":"Amen.","mark":"D"}],"Prelude":[{"k":"rubric","la":"Solemnis Actio liturgica celebranda est horis postmeridianis, et quidem circa horam tertiam; si vero ratio pastoralis id suadeat, inchoari potest inde a meridie, vel tardiori hora, non autem ultra horam nonam serotinam. Privata Actionis liturgicæ celebratio interdicitur. Hoc die sacra Communio fidelibus distribui potest unice inter solemnem Actionem liturgicam postmeridianam, exceptis iis, qui in periculo mortis sunt constituti."},{"k":"ref","la":"1. Altare omnino nudum sit: sine cruce, sine candelabris, sine tobaleis"},{"k":"rubric","la":"2. Solemnis Actio liturgica postmeridiana huius feriæ, ubi deest copia clericorum et sacerdotum, peragitur a celebrante cum assistentia ministrantium, ut suis locis notabitur; ubi vero clerici adsint, maxime convenit, ut in choro Actioni liturgicas assistant."},{"k":"rubric","la":"3. Itaque, unusquisque suis choralibus vestimentis induitur; celebrans et diaconus, amictu, alba et cingulo induti, sumunt stolam nigram; subdiaconus accipit amictum, albam et cingulum."},{"k":"rubric","la":"4. Omnibus sic paratis, incipit processio per ecclesiam ad altare, sub silentio."},{"k":"rubric","la":"5. Clerici, ministri, seu ministrantes, et celebrans, cum ad altare pervenerint, eidem altari reverentiam faciunt; deinde, celebrans et ministri sacri, non vero ministrantes, in faciem procumbunt, reliqui vero adeunt scamna in choro, ibique manent, genibus flexis et profunde inclinati: omnesque in silentio aliquamdiu orant."},{"k":"rubric","la":"6. Signo dato, omnes se erigunt, sed genuflexi manent; solus celebrans, stans ante gradus altaris, dicit, manibus iunctis et in tono feriali, sequentem orationem:"},{"k":"text","la":"Deus, qui peccáti véteris hereditáriam mortem, in qua posteritátis genus omne succésserat, Christi tui, Dómini nostri, passióne solvísti: da, ut, confórmes eídem facti; sicut imáginem terrénæ natúræ necessitáte portávimus, ita imáginem cœléstis grátiæ sanctificatióne portémus. Per eúndem Christum Dóminum nostrum. R. Amen.","mark":"V"},{"k":"sep"},{"k":"head","la":"I. Lectiones, Passio"},{"k":"rubric","la":"7. Oratione completa, celebrans et ministri, seu ministrantes, ad sedilia pergunt. Interim ponitur legile nudum in medio presbyterii, et lector incipit primam lectionem, omnibus sedentibus et auscultantibus. Incipitur vero sine titulo, ac clauditur absque Deo gratias."},{"k":"ref","la":"7 a. Deficiente lectore, ipse celebrans; stans in loco suo, legit lectionem"},{"k":"rubric","la":"Lectio prima"},{"k":"ref","la":"Osee 6:1-6"},{"k":"text","la":"Hæc dicit Dóminus: In tribulatióne sua mane consúrgent ad me: Veníte, et revertámur ad Dóminum: quia ipse cœpit, et sanábit nos: percútiet, et curábit nos. Vivificábit nos post duos dies: in die tértia suscitábit nos, et vivémus in conspéctu eius. Sciémus, sequemúrque, ut cognoscámus Dóminum: quasi dilúculum præparátus est egréssus eius, et véniet quasi imber nobis temporáneus, et serótinus terræ. Quid fáciam tibi Ephraim? quid fáciam tibi Iuda? Misericórdia vestra quasi nubes matutína, et quasi ros mane pertránsiens. Propter hoc dolávi in prophétis, occídi eos in verbis oris mei: et iudícia tua quasi lux egrediéntur. Quia misericórdiam vólui, et non sacrifícium, et sciéntiam Dei plus quam holocáusta."},{"k":"sep"},{"k":"rubric","la":"Sequitur responsorium, a schola cantandum, vel a clero assistente recitandum."},{"k":"rubric","la":"Responsorium"},{"k":"text","la":"Dómine, audívi audítum tuum, et tímui: considerávi ópera tua, et expávi.","mark":"V"},{"k":"text","la":"In médio duórum animálium innotescéris: dum appropinquáverint anni cognoscéris: dum advénerit, tempus, ostendéris.","mark":"V"},{"k":"text","la":"In eo, dum conturbáta fúerit ánima mea: in ira, misericórdiæ memor eris.","mark":"V"},{"k":"text","la":"Deus a Líbano véniet, et Sanctus de monte umbróso, et condénso.","mark":"V"},{"k":"text","la":"Opéruit cœlos maiéstas eius: et láudis eius plena est terra.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"8. Responsorio absoluto, omnes surgunt; celebrans, stans ad sedile, dicit Oremus, diaconus Flectamus genua, et omnes, flexis genibus, per aliquod temporis spatium in silentio orant; dicto a diacono Levate, omnes surgunt, et celebrans, manibus iunctis ac in tono feriali, dicit orationem."},{"k":"rubric","la":"8 a. Celebrans, manens in loco suo, dicit Oremus, Flectamus genua, et, brevi interposita precatione, flexis genibus et in silentio, dicit Levate; deinde surgit, et, manibus iunctis ac in tono feriali, dicit orationem."},{"k":"rubric","la":"Oratio"},{"k":"text","la":"Orémus.","mark":"V"},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Deus, a quo et Iudas reátus sui pœnam, et confessiónis suæ latro prǽmium sumpsit, concéde novis tuæ propitiatiónis efféctum: ut sicut in passióne sua Iesus Christus Dóminus noster divérsa utrísque íntulit stipéndia meritórum; ita nobis, abláto vetustátis erróre, resurrectiónis suæ grátiam largiátur:"},{"k":"macro","name":"Qui tecum"},{"k":"sep"},{"k":"rubric","la":"9. Oratione expleta, sequitur altera lectio, a subdiacono dicenda ad legile, item sine titulo, et sine Deo gratias in fine. Celebrans cetefique omnes, sedentes, auscultant."},{"k":"rubric","la":"9a. Lectionem legat lector ad legile: secus vero ipse celebrans, stans in loco suo."},{"k":"rubric","la":"Lectio"},{"k":"ref","la":"Exodus 12:1-11"},{"k":"text","la":"In diébus illis: Dixit Dóminus ad Móysen et Aaron in terra Ægýpti: Mensis iste, vobis princípium ménsium: primus erit in ménsibus anni. Loquímini ad univérsum cœtum filiórum Israël, et dícite eis: Décima die mensis huius tollat unusquísque agnum per famílias et domos suas. Sin autem minor est númerus, ut suffícere possit ad vescéndum agnum, assúmet vicínum suum qui iunctus est dómui suæ, iuxta númerum animárum quæ suffícere possunt ad esum agni. Erit autem agnus absque mácula, másculus, annículus: iuxta quem ritum tollétis et hædum. Et servábitis eum usque ad quartamdécimam diem mensis huius: immolabítque eum univérsa multitúdo filiórum Israël ad vésperam. Et sument de sánguine eius, ac ponent super utrúmque postem, et in superlimináribus domórum, in quibus cómedent illum. Et edent carnes nocte illa assas igni, et ázymos panes cum lactúcis agréstibus. Non comedétis ex eo crudum quid, nec coctum aqua, sed tantum assum igni: caput cum pédibus eius et intestínis vorábitis. Nec remanébit quidquam ex eo usque mane. Si quid resíduum fúerit, igne comburétis. Sic autem comedétis illum: renes vestros accingétis, et calceaménta habébitis in pédibus, tenéntes báculos in mánibus, et comedétis festinánter: est enim Phase - id est tránsitus - Dómini."},{"k":"sep"},{"k":"rubric","la":"Sequitur responsorium, a schola cantandum, vel a clero assistente recitandum."},{"k":"rubric","la":"Responsorium"},{"k":"ref","la":"Ps 139:2-10, 14"},{"k":"text","la":"Eripe me, Dómine, ab hómine malo: a viro iníquo líbera me.","mark":"V"},{"k":"text","la":"Qui cogitavérunt malítias in corde: tota die constituébant prǽlia.","mark":"V"},{"k":"text","la":"Acuérunt linguas suas sicut serpéntis: venénum áspidum sub lábiis eórum.","mark":"V"},{"k":"text","la":"Custódi me, Dómine, de manu peccatóris: et ab homínibus iníquis líbera me.","mark":"V"},{"k":"text","la":"Qui cogitavérunt supplantáre gressus meos: abscondérunt supérbi láqueum mihi.","mark":"V"},{"k":"text","la":"Et funes extendérunt in láqueum pédibus meis, iuxta iter scándalum posuérunt mihi.","mark":"V"},{"k":"text","la":"Dixi Dómino, Deus meus es tu: exáudi, Dómine, vocem oratiónis meæ.","mark":"V"},{"k":"text","la":"Dómine, Dómine virtus salútis meæ obúmbra caput meum in die belli.","mark":"V"},{"k":"text","la":"Ne tradas me a desidério meo peccatóri: cogitavérunt advérsus me: ne derelínquas me, ne unquam exalténtur.","mark":"V"},{"k":"text","la":"Caput circúitus eórum: labor labiórum ipsórum opériet eos.","mark":"V"},{"k":"text","la":"Verúmtamen iusti confitebúntur nómini tuo: et habitábunt recti cum vultu tuo.","mark":"V"},{"k":"sep"},{"k":"head","la":"Passio"},{"k":"rubric","la":"10. Absoluta altera lectione cum suo responsorio, ponuntur in latere Evangelii, in plano presbyterii, legilia nuda cum libris, et proceditur ad cantum vel lectionem historiæ Passionis Domini secundum Ioannem hoc modo: cantatur vel legitur a ministris, saltern in ordine diaconatus constitutis, qui, comitantibus duobus acolythis, vel ministrantibus, absque luminaribus et absque incenso, facta altari reverentia, ante celebrantem sistunt; media eos, profunde inclinatos, celebrans super voce dicit:"},{"k":"text","la":"Dominus sit in córdibus vestris et in lábiis vestris.","mark":"S"},{"k":"text","la":"Amen.","mark":"R"},{"k":"rubric","la":"10 a. Historiam Passionis Domini legit vel cantat celebrans, clara et distincta voce. Antequant incipiaty dicit, in medio presbyterii, profunde inclinatus, secreto: Dominus sit in corde meo et in labiis meis. Amen. Tune, fact a altari reverentia, vadit ad latus Evangelii, ibique, super nudum legile, incipit legere vel cantare historiam Passionis Domini."},{"k":"rubric","la":"Tunc, iterum facta altari reverentia, procedunt ad latus Evangelii, ibique, super nu dum legile, incipiunt cantare vel legere historiam Passionis Domini, omnibus auscultantibus."},{"k":"text","la":"Pássio Dómini nostri Iesu Christi secúndum Ioánnem."},{"k":"ref","la":"Joannes 18:1-40; 19:1-42"},{"k":"text","la":"In illo témpore: Egréssus est Iesus cum discípulis suis trans torréntem Cedron, ubi erat hortus, in quem introívit ipse, et discípuli eius. Sciébat autem et Iudas, qui tradébat eum, locum: quia frequénter Iesus convénerat illuc cum discípulis suis. Iudas ergo cum accepísset cohórtem, et a pontifícibus et pharisǽis minístros, venit illuc cum latérnis, et fácibus, et armis. Iesus ítaque sciens ómnia, quæ ventúra erant super eum, procéssit, et dixit eis: J. Quem quǽritis? C. Respondérunt ei: S. Iesum Nazarénum. C. Dicit eis Iesus: J. Ego sum. C. Stabat autem et Iudas, qui tradébat eum, cum ipsis. Ut ergo dixit eis: Ego sum: abiérunt retrórsum, et cecidérunt in terram. Iterum ergo interrogávit eos: J. Quem quǽritis? C. Illi autem dixérunt: S. Iesum Nazarénum. C. Respóndit Iesus: J. Dixi vobis, quia ego sum: si ergo me quǽritis, sínite hos abíre. C. Ut implerétur sermo, quem dixit: Quia quos dedísti mihi, non pérdidi ex eis quemquam. Simon ergo Petrus habens gládium edúxit eum: et percússit pontíficis servum: et abscídit aurículam eius déxteram. Erat autem nomen servo Malchus. Dixit ergo Iesus Petro: J. Mitte gládium tuum in vagínam. Cálicem, quem dedit mihi Pater, non bibam illum? C. Cohors ergo, et tribúnus, et minístri Iudæórum comprehendérunt Iesum, et ligavérunt eum: et adduxérunt eum ad Annam primum, erat enim socer Cáiphæ, qui erat póntifex anni illíus. Erat autem Cáiphas, qui consílium déderat Iudǽis: Quia éxpedit unum hóminem mori pro pópulo. Sequebátur autem Iesum Simon Petrus, et álius discípulus. Discípulus autem ille erat notus pontífici, et introívit cum Iesu in átrium pontíficis. Petrus autem stabat ad óstium foris. Exívit ergo discípulus álius, qui erat notus pontífici, et dixit ostiáriæ: et introdúxit Petrum. Dicit ergo Petro ancílla ostiária: S. Numquid et tu ex discípulis es hóminis istíus? C. Dicit ille: S. Non sum. C. Stabant autem servi, et minístri ad prunas, quia frigus erat, et calefaciébant se: erat autem cum eis et Petrus stans et calefáciens se. Póntifex ergo interrogávit Iesum de discípulis suis, et de doctrína eius. Respóndit ei Iesus: J. Ego palam locútus sum mundo: ego semper dócui in synagóga, et in templo, quo omnes Iudǽi convéniunt: et in occúlto locútus sum nihil. Quid me intérrogas? intérroga eos, qui audiérunt quid locútus sim ipsis: ecce hi sciunt quæ díxerim ego. C. Hæc autem cum dixísset, unus assístens ministrórum dedit álapam Iesu, dicens: S. Sic respóndes pontífici? C. Respóndit ei Iesus: J. Si male locútus sum, testimónium pérhibe de malo: si autem bene, quid me cædis? C. Et misit eum Annas ligátum ad Cáipham pontíficem. Erat autem Simon Petrus stans, et calefáciens se. Dixérunt ergo ei: S. Numquid et tu ex discípulis eius es? C. Negávit ille, et dixit: S. Non sum. C. Dicit ei unus ex servis pontíficis, cognátus eius, cuius abscídit Petrus aurículam: S. Nonne ego te vidi in horto cum illo? C. Iterum ergo negávit Petrus: et statim gallus cantávit. Addúcunt ergo Iesum a Cáipha in prætórium. Erat autem mane: et ipsi non introiérunt in prætórium, ut non contaminaréntur, sed ut manducárent pascha. Exívit ergo Pilátus ad eos foras, et dixit: S. Quam accusatiónem affértis advérsus hóminem hunc? C. Respondérunt et dixérunt ei: S. Si non esset hic malefáctor, non tibi tradidissémus eum. C. Dixit ergo eis Pilátus: S. Accípite eum vos, et secúndum legem vestram iudicáte eum. C. Dixérunt ergo ei Iudǽi: S. Nobis non licet interfícere quemquam. C. Ut sermo Iesu implerétur, quem dixit, signíficans qua morte esset moritúrus. Introívit ergo íterum in prætórium Pilátus, et vocávit Iesum, et dixit ei: S. Tu es Rex Iudæórum? C. Respóndit Iesus: J. A temetípso hoc dicis, an álii dixérunt tibi de me? C. Respóndit Pilátus: S. Numquid ego Iudǽus sum? Gens tua, et pontífices tradidérunt te mihi: quid fecísti? C. Respóndit Iesus: J. Regnum meum non est de hoc mundo. Si ex hoc mundo esset regnum meum, minístri mei útique decertárent ut non tráderer Iudǽis: nunc autem regnum meum non est hinc. C. Dixit ítaque ei Pilátus: S. Ergo Rex es tu? C. Respóndit Iesus: J. Tu dicis quia Rex sum ego. Ego in hoc natus sum, et ad hoc veni in mundum, ut testimónium perhíbeam veritáti: omnis, qui est ex veritáte, audit vocem meam. C. Dicit ei Pilátus: S. Quid est véritas? C. Et cum hoc dixísset, íterum exívit ad Iudǽos, et dicit eis: S. Ego nullam invénio in eo causam. Est autem consuetúdo vobis ut unum dimíttam vobis in Pascha: vultis ergo dimíttam vobis Regem Iudæórum? C. Clamavérunt ergo rursum omnes, dicéntes: S. Non hunc, sed Barábbam. C. Erat autem Barábbas latro. Tunc ergo apprehéndit Pilátus Iesum, et flagellávit. Et mílites plecténtes corónam de spinis, imposuérunt cápiti eius: et veste purpúrea circumdedérunt eum. Et veniébant ad eum, et dicébant: S. Ave Rex Iudæórum. C. Et dabant ei álapas. Exívit ergo íterum Pilátus foras, et dixit eis: S. Ecce addúco vobis eum foras, ut cognoscátis, quia nullam invénio in eo causam. C. Exívit ergo Iesus portans corónam spíneam, et purpúreum vestiméntum. Et dicit eis: S. Ecce homo. C. Cum ergo vidíssent eum pontífices et minístri, clamábant, dicéntes: S. Crucifíge, crucifíge eum. C. Dicit eis Pilátus: S. Accípite eum vos, et crucifígite: ego enim non invénio in eo causam. C. Respondérunt ei Iudǽi: S. Nos legem habémus, et secúndum legem debet mori, quia Fílium Dei se fecit. C. Cum ergo audísset Pilátus hunc sermónem, magis tímuit. Et ingréssus est prætórium íterum: et dixit ad Iesum: S. Unde es tu? C. Iesus autem respónsum non dedit ei. Dicit ergo ei Pilátus: S. Mihi non loquéris? Nescis quia potestátem hábeo crucifígere te, et potestátem hábeo dimíttere te? C. Respóndit Iesus: J. Non habéres potestátem advérsum me ullam, nisi tibi datum esset désuper. Proptérea, qui me trádidit tibi, maius peccátum habet. C. Et exínde quærébat Pilátus dimíttere eum. Iudǽi autem clamábant dicéntes: S. Si hunc dimíttis, non es amícus Cǽsaris. Omnis enim, qui se regem facit, contradícit Cǽsari. C. Pilátus autem cum audísset hos sermónes, addúxit foras Iesum, et sedit pro tribunáli, in loco, qui dícitur Lithóstrotos, hebráice autem Gábbatha. Erat autem Parascéve Paschæ, hora quasi sexta, et dicit Iudǽis: S. Ecce Rex vester. C. Illi autem clamábant: S. Tolle, tolle, crucifíge eum. C. Dicit eis Pilátus: S. Regem vestrum crucifígam? C. Respondérunt pontífices: S. Non habémus regem, nisi Cǽsarem. C. Tunc ergo trádidit eis illum ut crucifigerétur. Suscepérunt autem Iesum, et eduxérunt. Et báiulans sibi crucem, exívit in eum, qui dícitur Calváriæ, locum, hebráice autem Gólgotha: ubi crucifixérunt eum, et cum eo álios duos, hinc et hinc, médium autem Iesum. Scripsit autem et títulum Pilátus: et pósuit super crucem. Erat autem scriptum: Iesus Nazarénus, Rex Iudæórum. Hunc ergo títulum multi Iudæórum legérunt, quia prope civitátem erat locus, ubi crucifíxus est Iesus. Et erat scriptum hebráice, græce et latíne. Dicébant ergo Piláto pontífices Iudæórum: S. Noli scríbere, Rex Iudæórum, sed quia ipse dixit: Rex sum Iudæórum. C. Respóndit Pilátus: S. Quod scripsi, scripsi. C. Mílites ergo cum crucifixíssent eum, accepérunt vestiménta eius et fecérunt quátuor partes: unicuíque míliti partem, et túnicam. Erat autem túnica inconsútilis, désuper contéxta per totum. Dixérunt ergo ad ínvicem: S. Non scindámus eam, sed sortiámur de illa cuius sit. C. Ut Scriptúra implerétur, dicens: Partíti sunt vestiménta mea sibi: et in vestem meam misérunt sortem. Et mílites quidem hæc fecérunt. Stabant autem iuxta crucem Iesu, mater eius, et soror matris eius María Cléophæ, et María Magdaléne. Cum vidísset ergo Iesus matrem, et discípulum stantem, quem diligébat, dicit matri suæ: J. Múlier, ecce fílius tuus. C. Deínde dicit discípulo: J. Ecce mater tua. C. Et ex illa hora accépit eam discípulus in sua. Póstea sciens Iesus quia ómnia consummáta sunt, ut consummarétur Scriptúra, dixit: J. Sítio. C. Vas ergo erat pósitum acéto plenum. Illi autem spóngiam plenam acéto, hyssópo circumponéntes, obtulérunt ori eius. Cum ergo accepísset Iesus acétum, dixit: J. Consummátum est. C. Et inclináto cápite trádidit spíritum."},{"k":"rubric","la":"Hic genuflectitur, et pausatur aliquantulum."},{"k":"text","la":"Iudǽi ergo - quóniam Parascéve erat - ut non remanérent in cruce córpora sábbato - erat enim magnus dies ille sábbati - rogavérunt Pilátum, ut frangeréntur eórum crura, et tolleréntur. Venérunt ergo mílites: et primi quidem fregérunt crura, et altérius qui crucifíxus est cum eo. Ad Iesum autem cum veníssent, ut vidérunt eum iam mórtuum, non fregérunt eius crura: sed unus mílitum láncea latus eius apéruit, et contínuo exívit sanguis et aqua. Et qui vidit, testimónium perhíbuit: et verum est testimónium eius. Et ille scit, quia vera dicit: ut et vos credátis. Facta sunt enim hæc, ut Scriptúra implerétur: Os non comminuétis ex eo. Et íterum ália Scriptúra dicit: Vidébunt in quem transfixérunt. Post hæc autem rogávit Pilátum Ioseph ab Arimathǽa eo quod esset discípulus Iesu, occúltus autem propter metum Iudæórum, ut tólleret corpus Iesu. Et permísit Pilátus. Venit ergo, et tulit corpus Iesu. Venit autem et Nicodémus, qui vénerat ad Iesum nocte primum, ferens mixtúram myrrhæ, et áloës, quasi libras centum. Accepérunt ergo corpus Iesu, et ligavérunt illud línteis cum aromátibus, sicut mos est Iudǽis sepelíre. Erat autem in loco, ubi crucifíxus est, hortus: et in horto monuméntum novum, in quo nondum quisquam pósitus erat. Ibi ergo propter Parascéven Iudæórum, quia iuxta erat monuméntum, posuérunt Iesum."},{"k":"sep"},{"k":"head","la":"DE SECUNDA PARTE ACTIONIS LITURGICAE SEU DE ORATIONIBUS SOLEMNIBUS, QUAE ETIAM “ORATIO FIDELIUM” DICUNTUR"},{"k":"rubric","la":"12. Cantu vel lectione historiæ Passionis Domini absoluto, celebrans assumit pluviale nigri colotis; diaconus et subdiaconus induunt dalmaticam vel tunicellam eiusdem coloris. Interim vero duo acolythi, vel ministrantes, unam tantum tobaleam super altare extendunt, locantes librum in medio. Tune celebrans, comitantibus ministris, vel ministrantibus, accedit ad altare, quod, ascendens, osculatur in medio, et stans ibidem, ante se habens librum, incipit orationes solemnes, ministris sacris hinc inde adstantibus."},{"k":"rubric","la":"13. Dicuntur autem hoc ordine: Præcedit celebrantis præfatio, qua intentio specialis indicatur, et cantatur tono peculiari infra notato, manibus iunctis; deinde celebrans dicit Oremus, diaconus Flectamus genua, et omnes, flexis genibus, per aliquod temporis spatium in silentio orant; dicto a diacono Levate, omnes surgunt, et celebrans, extensis manibus ac in tono feriali, dicit orationem."},{"k":"rubric","la":"13 a. Celebrans dicit Oremus, Flectamus genua, et, brevi interposita precatione, flexis genibus et in silentio, dicit Levate, deinde surgit, et, extensis manibus ac in tono feriali, dicit orationem."},{"k":"text","la":"Orémus, dilectíssimi nobis, pro Ecclésia sancta Dei: ut eam Deus et Dóminus noster pacificáre, adunáre, et custodíre dignétur toto orbe terrárum: subíciens ei principátus, et potestátes: detque nobis quiétam et tranquíllam vitam degéntibus, glorificáre Deum Patrem omnipoténtem.","mark":"V"},{"k":"text","la":"Orémus.","mark":"S"},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Omnípotens sempitérne Deus, qui glóriam tuam ómnibus in Christo géntibus revelásti: custódi ópera misericórdiæ tuæ; ut Ecclésia tua toto orbe diffúsa, stábili fide in confessióne tui nóminis persevéret. Per eúndem Dóminum nostrum Iesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus et pro beatíssimo Papa nostro N., ut Deus et Dóminus noster, qui elégit eum in órdine episcopátus, salvum atque incólumem custódiat Ecclésiæ suæ sanctæ, ad regéndum pópulum sanctum Dei.","mark":"V"},{"k":"text","la":"Orémus.","mark":"S"},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Omnípotens sempitérne Deus, cuius iudício univérsa fundántur: réspice propítius ad preces nostras, et eléctum nobis Antístitem tua pietáte consérva; ut christiána plebs, quæ te gubernátur auctóre, sub tanto pontífice, credulitátis suæ méritis augeátur. Per Dóminum nostrum Iesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus et pro ómnibus Epíscopis, Presbýteris, Diacónibus, Subdiacónibus, Acólythis, Exorcístis, Lectóribus, Ostiáriis, Confessóribus, Virgínibus, Víduis: et pro omni pópulo sancto Dei.","mark":"V"},{"k":"text","la":"Orémus.","mark":"S"},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Omnípotens sempitérne Deus, cuius spíritu totum corpus Ecclésiæ sanctificátur et régitur: exáudi nos pro univérsis ordínibus supplicántes; ut grátiæ tuæ múnere, ab ómnibus tibi grádibus fidéliter serviátur. Per Dóminum nostrum Iesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte eiúsdem Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus et pro ómnibus res públicas moderántibus, eorúmque ministériis et potestátibus: ut Deus et Dóminus noster mentes et corda eórum secúndum voluntátem suam dírigat ad nostram perpétuam pacem.","mark":"V"},{"k":"text","la":"Orémus.","mark":"S"},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Omnípotens sempitérne Deus, in cuius manu sunt ómnium potestátes et ómnium iura populórum: réspice benígnus ad eos, qui nos in potestáte regunt; ut ubíque terrárum, déxtera tua protegénte, et religiónis intégritas, et pátriæ secúritas indesinénter consístat. Per Dóminum nostrum Iesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus et pro catechúmenis nostris: ut Deus et Dóminus noster adapériat áures præcordiórum ipsórum, ianuámque misericórdiæ; ut per lavácrum regeneratiónis accépta remissióne ómnium peccatórum, et ipsi inveniántur in Christo Iesu Dómino nostro.","mark":"V"},{"k":"text","la":"Orémus.","mark":"S"},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Omnípotens sempitérne Deus, qui Ecclésiam tuam nova semper prole fœcúndas: áuge fidem et intelléctum catechúmenis nostris; ut renáti fonte baptísmatis, adoptiónis tuæ fíliis aggregéntur. Per Dóminum nostrum Iesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus, dilectíssimi nobis, Deum Patrem omnipoténtem, ut cunctis mundum purget erróribus: morbos áuferat: famem depéllat: apériat cárceres: víncula dissólvat: peregrinántibus réditum: infirmántibus sanitátem: navigántibus portum salútis indúlgeat.","mark":"V"},{"k":"text","la":"Orémus.","mark":"S"},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Omnípotens sempitérne Deus, mœstórum consolátio, laborántium fortitúdo: pervéniant ad te preces de quacúmque tribulatióne clamántium; ut omnes sibi in necessitátibus suis misericórdiam tuam gáudeant affuísse. Per Dóminum nostrum Iesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus et pro hæréticis et schismáticis: ut Deus et Dóminus noster éruat eos ab erróribus univérsis; et ad sanctam matrem Ecclésiam Cathólicam atque Apostólicam revocáre dignétur.","mark":"V"},{"k":"text","la":"Orémus.","mark":"S"},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Omnípotens sempitérne Deus, qui salvas omnes, et néminem vis períre: réspice ad ánimas diabólica fráude decéptas; ut omni hærética pravitáte depósita, errántium corda resipíscant, et ad veritátis tuæ rédeant unitátem. Per Dóminum nostrum Iesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus et pro pérfidis Iudǽis: ut Deus et Dóminus noster áuferat velámen de córdibus eórum; ut et ipsi agnóscant Iesum Christum Dóminum nostrum.","mark":"V"},{"k":"text","la":"Orémus.","mark":"S"},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Omnípotens sempitérne Deus, qui Iudǽos étiam a tua misericórdia non repéllis: exáudi preces nostras, quas pro illíus pópuli obcæcatióne deférimus; ut, ágnita veritátis tuæ luce, quæ Christus est, a suis ténebris eruántur. (sed rubríca 1960) V. Omnípotens sempitérne Deus, qui vis ut omnes hómines salvi fiant et ad agnitiónem veritátis véniant, concéde propítius, ut plenitúdine géntium in Ecclésiam Tuam intránte omnis Israël salvus fiat. Per eúndem Dóminum nostrum Iesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"text","la":"Orémus et pro pagánis: ut Deus omnípotens áuferat iniquitátem a córdibus eórum; ut relíctis idólis suis, convertántur ad Deum vivum et verum, et únicum Fílium eius Iesum Christum Deum et Dóminum nostrum.","mark":"V"},{"k":"text","la":"Orémus.","mark":"S"},{"k":"text","la":"Flectámus génua.","mark":"V"},{"k":"text","la":"Leváte.","mark":"R"},{"k":"text","la":"Omnípotens sempitérne Deus, qui non mortem peccatórum, sed vitam semper inquíris: súscipe propítius oratiónem nostram, et líbera eos ab idolórum cultúra; et ággrega Ecclésiæ tuæ sanctæ ad láudem et glóriam nóminis tui. Per Dóminum nostrum Iesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","mark":"V"},{"k":"text","la":"Amen.","mark":"R"},{"k":"sep"},{"k":"head","la":"DE TERTIA PARTE ACTIONIS LITURGICE SEU DE SOLEMNI SANCTAE CRUCIS ADORATIONE"},{"k":"sep"},{"k":"rubric","la":"14. Orationibus solemnibus completis, celebrans et ministri redeunt ad sedilia, ubi celebrans deponit pluviale, ministri dalmaticam vel tunicellam; et datur initium solemni adorationi sanctæ Crucis. Adhibeatur Crux satis magna, cum Crucifixo, velo violaceo obtecto, quod facile removere possit."},{"k":"rubric","la":"15. Primum portatur sancta Crux e sacristia in medium presbyterii, omnibus stantibus. Portatur autem hoc modo: Celebrans et subdiaconus manent ad sedilia stantes: diaconus cum acolythis, seu ministrantibus, adit sacristiam, ex qua processionaliter affert Crucem ad ecclesiam: præcedunt acolythi, seu ministrantes, sequitur diaconus cum Cruce, medius inter alios duos acolythos, seu ministrantes, candelabra accensa gestantes. Cum presbyterium ingressi fuerint, celebrans et subdiaconus ipsis obviam veniunt, et in medio, ante altare, celebrans Crucem e manibus diaconi accipit."},{"k":"rubric","la":"15a. Celebrans cum ministrantibus sacristiam adit, indeque, ut supra, portat Crucem ante altare."},{"k":"rubric","la":"16. Tum proceditur ad detectionem sanctæ Crucis, hoc modo: Celebrans, accedens ad latus Epistolæ, ibique, stans in plano, versa facie ad populum, Crucem a summitate parum detegit. Deinde solus incipit antiphonam Ecce lignum Crucis, ac deinceps iuvatur in cantu a ministris sacris, usque ad Venite, adoremus, quod cantatur a schola, comitantibus omnibus adstantibus. Cantu finito, omnes in genua se prosternunt, celebrante excepto, et parvo momento in silentio adorant. Deinde celebrans ascendit altare in latere Epistolæ, et detegit bracchium dextrum Crucifixi; tunc elevans Crucem paulisper, adiuvantibus, si opus sit, ministris sacris, altius quam primo cantat iterum Ecce lignum Crucis, aliis prosequentibus, et, post cantum, procumbentibus, ut supra. Denique celebrans procedit ad medium altaris, et detegit Crucem totaliter, ac elevans eam, tertio altius incipit Ecce lignum Crucis, aliis, ut supra, prosequentibus, et post cantum adorantibus. Duo autem acolythi, seu ministrantes, cum candelabris accensis comitantur Crucem, a dextris et a sinistris celebrantis."},{"k":"rubric","la":"16 a. Celebrans, in detegenda sancta Cruce, adiuvatur a ministrantibus; antiphonam vero Ecce lignum Crucis, usque ad Venite, adoremus, cantat solus."},{"k":"text","la":"Ecce lignum Crucis, in quo salus mundi pepéndit.","mark":"V"},{"k":"text","la":"Veníte, adorémus.","mark":"R"},{"k":"text","la":"Ecce lignum Crucis, in quo salus mundi pepéndit.","mark":"V"},{"k":"text","la":"Veníte, adorémus.","mark":"R"},{"k":"text","la":"Ecce lignum Crucis, in quo salus mundi pepéndit.","mark":"V"},{"k":"text","la":"Veníte, adorémus.","mark":"R"},{"k":"rubric","la":"17. Post detectionem Crucis sequitur eiusdem solemnis adoratio, hoc modo: Crux, postquam detecta fuerit, traditur a celebrante duobus acolythis, vel ministrantibus, qui stantes in suppedaneo, ante medium altaris, et facie ad populum versa, eam hinc inde ita per bracchia sustentant, ut pes Crucis super suppedaneum consistat. Alii vero duo acolythi, vel ministrantes, qui candelabra accensa gestabant, eisdem candelabris a dextris et a sinistris Crucis super suppedaneum collocatis, genuflexi manent in later ibus suppedanei, in superiore gradu, facie versus Crucem. Tune incipit adoratio sanctæ Crucis, ordine sequenti: primus accedit solus celebrans; deinde ministri, postea clerus, demum ministrantes. Hi omnes, si commode fieri possit, prius calceamenta deponunt, et, unus post alium, accedentes ad Crucem, simplici genuflexione ter repetita, pedes Crucifixi osculantur."},{"k":"rubric","la":"18. Sancta Crux, adoratione ex parte celebrantis, ministrorum, cleri ac ministrantium peracta, a duobus acolythis, seu ministrantibus, comitantibus aliis duobus acolythis, seu ministrantibus, cum candelabris accensis, defertur ad cancellos, et ibidem sustentatur eodem modo, ut supra, ita ut fideles, ante Crucem quasi processionaliter transeuntes, primum viri, deinde mulieres, pedes Crucifixi devote deosculari possint, præmissa simplici genuflexione. Si parochus aut rector ecclesiæ prævideat, adorationem sanctae Crucis, prout supra præscribitur, ob ingentem populi concursum, vix aut non sine boni ordinis et devotionis detrimento peragi posse, tune cæremonia hoc modo peragitur: celebrans, postquam clerus, si adsit, et ministrantes adorationem expleverint, sanctam Crucem e manibus ministrantium sumat et, in summitate graduum altaris consistens, paucis verbis populum ad sanctae Crucis adorationem invitet eamque altius elevatam teneat, per breve tempus a fidelibus in silentio adorandam."},{"k":"rubric","la":"19. Dum autem sanctse Crucis adoratio peragitur, cantantur a schola, in duos choros divisa, sic dicta Improperia, et alia quæ sequuntur; celebrans, ministri sacri, et ministrantes, ceterique omnes, qui adorationem sanctæ Crucis peregerunt, sedentes auscultant. Cantus vero eousque producitur, prout adorantium numerus requirit. Concluditur tamen semper cum doxologia: Sempiteina sit beatæ Trinitati gloria, ut infra."},{"k":"rubric","la":"IMPROPERIA"},{"k":"rubric","la":"Partes quæ ad singulos choros spectant, indicantur numeris 1 (chorus primus), et 2 (chorus secundus); quæ autem ab utroque choro simul cantanda sunt, indicantur hoc modo: 1 et 2."},{"k":"ref","la":"1 et 2"},{"k":"text","la":"Pópule meus, quid feci tibi? aut in quo contristávi te? Respónde mihi.","mark":"V"},{"k":"text","la":"Quia edúxi te de terra Ægýpti, parásti crucem Salvatóri tuo.","mark":"V"},{"k":"ref","la":"1"},{"k":"text","la":"Agios o Theós!","mark":"R"},{"k":"ref","la":"2"},{"k":"text","la":"Sanctus Deus!","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Agios ischyrós!","mark":"R"},{"k":"ref","la":"2"},{"k":"text","la":"Sanctus fortis!","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Agios athánatos, eléison imas.","mark":"R"},{"k":"ref","la":"2"},{"k":"text","la":"Sanctus immortális, miserére nobis.","mark":"R"},{"k":"ref","la":"1 et 2"},{"k":"text","la":"Quia edúxi te per desértum quadragínta annis, et manna cibávi te, et introdúxi te in terram satis bonam: parásti Crucem Salvatóri tuo.","mark":"V"},{"k":"ref","la":"1"},{"k":"text","la":"Agios o Theós!","mark":"R"},{"k":"ref","la":"2"},{"k":"text","la":"Sanctus Deus!","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Agios ischyrós!","mark":"R"},{"k":"ref","la":"2"},{"k":"text","la":"Sanctus fortis!","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Agios athánatos, eléison imas.","mark":"R"},{"k":"ref","la":"2"},{"k":"text","la":"Sanctus immortális, miserére nobis.","mark":"R"},{"k":"ref","la":"1 et 2"},{"k":"text","la":"Quid ultra débui fácere tibi, et non feci? Ego quidem plantávi te víneam meam speciosíssimam: et tu facta es mihi nimis amára: acéto namque sitim meam potásti: et láncea perforásti latus Salvatóri tuo.","mark":"V"},{"k":"text","la":"Agios o Theós!","mark":"R"},{"k":"text","la":"Sanctus Deus!","mark":"R"},{"k":"text","la":"Agios ischyrós!","mark":"R"},{"k":"text","la":"Sanctus fortis!","mark":"R"},{"k":"text","la":"Agios athánatos, eléison imas.","mark":"R"},{"k":"text","la":"Sanctus immortális, miserére nobis.","mark":"R"},{"k":"sep"},{"k":"ref","la":"1"},{"k":"text","la":"Ego propter te flagellávi Ægýptum cum primogénitus suis: et tu me flagellátum tradidísti.","mark":"V"},{"k":"ref","la":"2"},{"k":"text","la":"Pópule meus, quid feci tibi? aut in quo contristávi te? Respónde mihi.","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Ego edúxi te de Ægýpto, demérso Pharaóne in Mare Rubrum: et tu me tradidísti princípibus sacerdótum.","mark":"V"},{"k":"ref","la":"2"},{"k":"text","la":"Pópule meus, quid feci tibi? aut in quo contristávi te? Respónde mihi.","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Ego ante te apérui mare: et tu aperuísti láncea latus meum.","mark":"V"},{"k":"ref","la":"2"},{"k":"text","la":"Pópule meus, quid feci tibi? aut in quo contristávi te? Respónde mihi.","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Ego ante te præívi in colúmna nubis: et tu me duxísti ad prætórium Piláti.","mark":"V"},{"k":"ref","la":"2"},{"k":"text","la":"Pópule meus, quid feci tibi? aut in quo contristávi te? Respónde mihi.","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Ego te pavi manna per desértum: et tu me cecidísti álapis et flagéllis.","mark":"V"},{"k":"ref","la":"2"},{"k":"text","la":"Pópule meus, quid feci tibi? aut in quo contristávi te? Respónde mihi.","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Ego te potávi aqua salútis de petra: et tu me potásti felle, et acéto.","mark":"V"},{"k":"ref","la":"2"},{"k":"text","la":"Pópule meus, quid feci tibi? aut in quo contristávi te? Respónde mihi.","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Ego propter te Chananæórum reges percússi: et tu percussísti arúndine caput meum.","mark":"V"},{"k":"ref","la":"2"},{"k":"text","la":"Pópule meus, quid feci tibi? aut in quo contristávi te? Respónde mihi.","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Ego dedi tibi sceptrum regále: et tu dedísti cápiti meo spíneam corónam.","mark":"V"},{"k":"ref","la":"2"},{"k":"text","la":"Pópule meus, quid feci tibi? aut in quo contristávi te? Respónde mihi.","mark":"R"},{"k":"ref","la":"1"},{"k":"text","la":"Ego te exaltávi magna virtúte: et tu me suspendísti in patíbulo Crucis.","mark":"V"},{"k":"ref","la":"2"},{"k":"text","la":"Pópule meus, quid feci tibi? aut in quo contristávi te? Respónde mihi.","mark":"R"},{"k":"ref","la":"1 et 2 Antiphóna"},{"k":"text","la":"Ant. Crucem tuam * adorámus, Dómine: et sanctam resurrectiónem tuam laudámus, et glorificámus: ecce enim propter lignum venit gáudium in univérso mundo."},{"k":"ref","la":"1"},{"k":"text","la":"Deus misereátur nostri, et benedícat nobis."},{"k":"ref","la":"2"},{"k":"text","la":"Illúminet vultum suum super nos, et misereátur nostri."},{"k":"ref","la":"1 et 2 Antiphóna"},{"k":"text","la":"Ant. Crucem tuam * adorámus, Dómine: et sanctam resurrectiónem tuam laudámus, et glorificámus: ecce enim propter lignum venit gáudium in univérso mundo."},{"k":"sep"},{"k":"rubric","la":"CRUX FIDELIS"},{"k":"ref","la":"1 et 2 Antiphona:"},{"k":"text","la":"Ant. Crux fidélis, inter omnes Arbor una nóbilis! Nulla silva talem profert, Fronde, flore, gérmine, * Dulce lignum, dulces clavos, Dulce pondus sústinet."},{"k":"ref","la":"1 Hymnus"},{"k":"text","la":"Pange, lingua, gloriósi,","mark":"V"},{"k":"text","la":"Láuream certáminis,"},{"k":"text","la":"Et super Crucis trophǽo"},{"k":"text","la":"Dic triúmphum nóbilem:"},{"k":"text","la":"Quáliter Redémptor orbis"},{"k":"text","la":"Immolátus vícerit."},{"k":"text","la":"_ `"},{"k":"ref","la":"2"},{"k":"text","la":"Ant. Crux fidélis, inter omnes Arbor una nóbilis! Nulla silva talem profert, Fronde, flore, gérmine."},{"k":"ref","la":"1"},{"k":"text","la":"De paréntis protoplásti","mark":"V"},{"k":"text","la":"Fráude Factor cóndolens,"},{"k":"text","la":"Quando pomi noxiális"},{"k":"text","la":"In necem morsu ruit:"},{"k":"text","la":"Ipse lignum tunc notávit."},{"k":"text","la":"Damna ligni ut sólveret."},{"k":"text","la":"_ `"},{"k":"ref","la":"2"},{"k":"text","la":"Ant. Dulce lignum, dulces clavos, Dulce pondus sústinet."},{"k":"ref","la":"1"},{"k":"text","la":"Hoc opus nostræ salútis","mark":"V"},{"k":"text","la":"Ordo depopóscerat:"},{"k":"text","la":"Multifórmis proditóris"},{"k":"text","la":"Ars ut artem fálleret:"},{"k":"text","la":"Et medélam ferret inde,"},{"k":"text","la":"Hostis unde lǽserat."},{"k":"text","la":"_ `"},{"k":"ref","la":"2"},{"k":"text","la":"Ant. Crux fidélis, inter omnes Arbor una nóbilis! Nulla silva talem profert, Fronde, flore, gérmine."},{"k":"ref","la":"1"},{"k":"text","la":"Quando venit ergo sacri","mark":"V"},{"k":"text","la":"Plenitúdo témporis,"},{"k":"text","la":"Missus est ab arce Patris"},{"k":"text","la":"Natus, orbis Cónditor:"},{"k":"text","la":"Atque ventre virgináli"},{"k":"text","la":"Carne amíctus pródiit."},{"k":"text","la":"_ `"},{"k":"ref","la":"2"},{"k":"text","la":"Ant. Dulce lignum, dulces clavos, Dulce pondus sústinet."},{"k":"ref","la":"1"},{"k":"text","la":"Vagit infans inter arcta","mark":"V"},{"k":"text","la":"Cónditus præsépia:"},{"k":"text","la":"Membra pannis involúta"},{"k":"text","la":"Virgo Mater álligat:"},{"k":"text","la":"Et Dei manus, pedésque"},{"k":"text","la":"Stricta cingit fáscia."},{"k":"text","la":"_ `"},{"k":"ref","la":"2"},{"k":"text","la":"Ant. Crux fidélis, inter omnes Arbor una nóbilis! Nulla silva talem profert, Fronde, flore, gérmine."},{"k":"ref","la":"1"},{"k":"text","la":"Lustra sex qui iam perégit,","mark":"V"},{"k":"text","la":"Tempus implens córporis,"},{"k":"text","la":"Sponte líbera Redémptor"},{"k":"text","la":"Passióni déditus,"},{"k":"text","la":"Agnus in Crucis levátur"},{"k":"text","la":"Immolándus stípite."},{"k":"text","la":"_ `"},{"k":"ref","la":"2"},{"k":"text","la":"Ant. Dulce lignum, dulces clavos, Dulce pondus sústinet."},{"k":"ref","la":"1"},{"k":"text","la":"Felle potus ecce languet:","mark":"V"},{"k":"text","la":"Spina, clavi, láncea,"},{"k":"text","la":"Mite corpus perforárunt,"},{"k":"text","la":"Unda manat, et cruor:"},{"k":"text","la":"Terra, pontus, astra, mundus."},{"k":"text","la":"Quo lavántur flúmine!"},{"k":"text","la":"_ `"},{"k":"ref","la":"2"},{"k":"text","la":"Ant. Crux fidélis, inter omnes Arbor una nóbilis! Nulla silva talem profert, Fronde, flore, gérmine."},{"k":"ref","la":"1"},{"k":"text","la":"Flecte ramos, arbor alta,","mark":"V"},{"k":"text","la":"Tensa lax víscera,"},{"k":"text","la":"Et rigor lentéscat ille,"},{"k":"text","la":"Quem dedit natívitas:"},{"k":"text","la":"Et supérni membra Regis"},{"k":"text","la":"Tende miti stípite."},{"k":"text","la":"_ `"},{"k":"ref","la":"2"},{"k":"text","la":"Ant. Dulce lignum, dulces clavos, Dulce pondus sústinet."},{"k":"ref","la":"1"},{"k":"text","la":"Sola digna tu fuísti","mark":"V"},{"k":"text","la":"Ferre mundi víctimam:"},{"k":"text","la":"Atque portum præparáre"},{"k":"text","la":"Arca mundo naúfrago:"},{"k":"text","la":"Quam sacer cruor perúnxit,"},{"k":"text","la":"Fusus Agni córpore."},{"k":"text","la":"_ `"},{"k":"ref","la":"2"},{"k":"text","la":"Ant. Crux fidélis, inter omnes Arbor una nóbilis! Nulla silva talem profert, Fronde, flore, gérmine."},{"k":"rubric","la":"Conclusio numquam omittenda:"},{"k":"ref","la":"1"},{"k":"text","la":"Sempitérna sit beátæ","mark":"V"},{"k":"text","la":"Trinitáti glória:"},{"k":"text","la":"Æqua Patri, Filióque;"},{"k":"text","la":"Par decus Paráclito:"},{"k":"text","la":"Unus Triníque nomen"},{"k":"text","la":"Láudet univérsitas."},{"k":"text","la":"Amen."},{"k":"ref","la":"2"},{"k":"text","la":"Ant. Dulce lignum, dulces clavos, Dulce pondus sústinet."},{"k":"sep"},{"k":"rubric","la":"20. Adoratione Crucis expleta, ipsa Crux ab acolythis, vel ministrantibus, qui eam sustentaverant, comitantibus aliis duobus acolythis, vel ministrantibus, cum candelabris accensis, reportatur ad altare, ibique collocatur in medio, et quidem, si altaris dispositio id permittat, adeo in altum ut commode a fidelibus conspici possit, quin celebranti in cæremoniis sequentibus, super altare peragendis, incommodum præbeat. Candelabra vero accensa deponuntur super altare."},{"k":"rubric","la":"21. Postea celebrans et diaconus, dimissa stola nigri coloris, assumunt paramenta violacea, scilicet celebrans stolam et planetam, diaconus stolam et dalmaticam, subdiaconus vero tunicellam."},{"k":"rubric","la":"22. Deinde diaconus, delata bursa super altare, extendit corporale, more solito; acolythus autem, vel ministrans, deponit super altare vas aquæ cum purificatorio, ad abluendos et abstergendos digitos post Communionem, et librum disponit in latere Evangelii."},{"k":"rubric","la":"22 a. Antequam processio inchoetur, sacerdos defert et explicat corporale super altare, more solito."},{"k":"rubric","la":"23. Rebus ita dispositis, reportatur Sacramentum e loco repositionis ad altare maius pro Communione peragenda. Portatur autem hoc modo: Celebrans et subdiaconus, clerus et populus manent in suis locis, sub silentio. Diaconus cum duobus acolythis, et alio clerico ad umbellam portandam, accedunt ad altare repositionis, in quo præsto sint duo candelabra cum cereis accensis, postmodum ab acolythis sumenda. Ad altare repositionis genua flectunt; tune diaconus extrahit sacram pyxidem e tabernaculo seu capsa, et, assumpto velo humerali albi coloris, pyxidem extremitatibus eiusdem veli cooperit et ad altare maius defert."},{"k":"ref","la":"23 a. Omnia fiunt per ipsum celebrantem cum suis ministrantibus"},{"k":"rubric","la":"24. Procedunt ordine quo venerunt; super Sacramentum defertur umbella; acolythi hinc inde procedentes candelabra accensa gestant, omnes in genua procumbunt. Interim schola cantat sequentes antiphonas:"},{"k":"text","la":"Adorámus te, Christe, et benedícimus tibi, quia per Crucem tuam redemísti mundum.","mark":"V"},{"k":"text","la":"Per lignum servi facti sumus, et per sanctam Crucem liberáti sumus: fructus árboris sedúxit nos, Fílius Dei redémit nos.","mark":"V"},{"k":"text","la":"Salvátor mundi, salva nos: qui per Crucem et Sánguinem tuum redemísti nos, auxiliáre nobis, te deprecámur, Deus noster.","mark":"V"},{"k":"sep"},{"k":"head","la":"Communio"},{"k":"rubric","la":"25. Cum ad altare maius pervenerint, illud ascendunt, diaconus sacram pyxidem super corporale, acolythi autem candelabra super altare deponunt. Genuflexione peracta, diaconus dimittit velum humerale et se retrahit ad latus Epistolæ; acolythi vero descendunt hinc inde, et genuflectunt in infimo gradu altaris."},{"k":"rubric","la":"26. Tunc celebrans et subdiaconus accedunt ad altare, utroque genu adorant, illud ascendunt, et facta, una cum diacono, genuflexione, celebrans clara voce recitat, non cantat, præfationem orationis dominicse Oremus. Præceptis salutaribus moniti. Totum vero Pater noster, cum sit precatio ad Communionem, omnes præsentes, clerici et fideles, una cum celebrante, solemniter, graviter et distincte recitant, lingua latina addito quoque ab omnibus Amen. Celebrans, iunctis manibus, dicit solus:"},{"k":"text","la":"Oremus.","mark":"V"},{"k":"text","la":"Præcéptis salutáribus móniti, et divína institutióne formǽti, audémus dícere:"},{"k":"rubric","la":"Celebrans, item iunctis manibus, et omnes præsentes prosequuntur:"},{"k":"text","la":"Pater noster, qui es in coelis, sanctificetur nomen tuum. Adveniat regnum tuum. Fiat voluntas tua, sicut in coelo, et in terra. Panem nostrum cotidianum da nobis hodie: et dimitte nobis debita nostra, sicut et nos dimittibus debitoribus nostris. Et ne nos inducas in tentationem; sed libera nos a malo. Amen.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"27. Celebrans solus, clara et distincta voce atque manibus extensis, prosequitur:"},{"k":"text","la":"Líbera nos, quǽsumus, Dómine, ab ómnibus malis, prætéritis, præséntibus, et futúris: et intercedénte beáta et gloriósa semper Vírgine Dei Genetríce María, cum beátis Apóstolis tuis Petro et Paulo, atque Andréa, et ómnibus Sanctis, da propítius pacem in diébus nostris: ut ope misericórdiæ tuæ adiúti, et a peccáto simus semper líberi, et ab omni perturbatióne secúri. Per eúmdem Dóminum nostrum Iesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","mark":"V"},{"k":"rubric","la":"Et ab omnibus respondetur:"},{"k":"text","la":"Amen.","mark":"R"},{"k":"text","la":"_ `"},{"k":"rubric","la":"28. Et continuo celebrans recitat, submissa voce, sequentem orationem, de more inclinatus, manibusque iunctis super altare positis:"},{"k":"text","la":"Percéptio Córporis tui, Dómine Iesu Christe, quod ego indígnus súmere præsúmo, non mihi provéniat in iudícium et condemnatiónem: sed pro tua pietáte prosit mihi ad tutaméntum mentis, et córporis, et ad medélam percipiéndam. Qui vivis et regnas cum Deo Patre in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum. Amen.","mark":"V"},{"k":"text","la":"_ `"},{"k":"rubric","la":"29. Turn discooperit pyxidem, et, facta genuflexione, accipit sacram particulam, et, tenens illam supra pyxidem, inclinatus et pectus percutiens, ter dicit, more solito:"},{"k":"text","la":"Dómine, non sum dignus, ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.","mark":"V"},{"k":"text","la":"Dómine, non sum dignus, ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.","mark":"V"},{"k":"text","la":"Dómine, non sum dignus, ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.","mark":"V"},{"k":"ref","la":"30. Postea, signans se Sacramento, adiungit submissa voce:"},{"k":"text","la":"Corpus Dómini nostri Iesu Christi custódiat ánimam meam in vitam ætérnam. Amen.","mark":"V"},{"k":"rubric","la":"Et sumit Corpus reverenter, ac paululum in meditatione Sacramenti quiescit."},{"k":"rubric","la":"31. Et continuo diaconus facit confessionem. Tunc celebrans, facta genuflexione, conversus ad populum, manibus iunctis ante pectus, clara voce dicit:"},{"k":"text","la":"Misereátur vestri omnípotens Deus, et, dimíssis peccátis vestris, perdúcat vos ad vitam ætérnam.","mark":"V"},{"k":"rubric","la":"Omnes respondent:"},{"k":"text","la":"Amen."},{"k":"rubric","la":"Celebrans prosequitur:"},{"k":"text","la":"Indulgéntiam, absolutiónem + et remissiónem peccatórum vestrórum tríbuat vobis omnípotens et miséricors Dóminus.","mark":"V"},{"k":"rubric","la":"Omnes respondent:"},{"k":"text","la":"Amen."},{"k":"rubric","la":"32. Deinde ad altare se convertit, genuflectit, apprehendit pyxidem, et more solito conversus ad populum, in medio altaris, dicit clara voce:"},{"k":"text","la":"Ecce Agnus Dei, ecce qui tollit peccáta mundi."},{"k":"rubric","la":"Mox subdit:"},{"k":"text","la":"Dómine, non sum dignus, ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea."},{"k":"rubric","la":"quod iterum ac tertio repetit."},{"k":"rubric","la":"Et procedit ad distributionem Communionis, ut supra feria V in Cena Domini, 159, n. 29, dictum est. Sacerdotes vero stolam violaceam deferunt."},{"k":"rubric","la":"33. Dum sacra Communio distribuitur, cani potest psalmus 21 Deus meus, Deus meus; vel unum aliudve responsorium ex Matutino huius feriæ VI."},{"k":"rubric","la":"34. Communione absoluta, celebrans digitos abluit in vase, ac purificatorio abstergit, nihil dicens; pyxidem vero in tabernaculo reponit."},{"k":"rubric","la":"35. His completis, celebrans stans in medio altaris, habens ante se librum, a dextris et a sinistris ministros sacros, dicit pro gratiarum actione, in tono feriali et manibus iunctis, tres sequentes orationes, omnibus stantibus et Amen respondentibus."},{"k":"sep"},{"k":"text","la":"Orémus.","mark":"V"},{"k":"text","la":"Super pópulum tuum quǽsumus, Dómine, qui passiónem et mortem Fílii tui devóta mente recóluit, benedíctio copiósa descéndat, indulgéntia véniat, consolátio tribuátur, fides sancta succréscat, redémptio sempitérna firmétur. Per eúndem Christum Dóminum nostrum. Amen."},{"k":"text","la":"Amen.","mark":"R"},{"k":"text","la":"_ `"},{"k":"text","la":"Oremus.","mark":"V"},{"k":"text","la":"Omnípotens et miséricors Deus, qui Christi tui beáta passióne et morte nos reparásti: consérva in nobis óperam misericórdiæ tuæ; ut huius mystérii participatióne, perpétua devotióne vivámus. Per eúndem Christum Dóminum nostrum. Amen."},{"k":"text","la":"Amen.","mark":"R"},{"k":"text","la":"_ `"},{"k":"text","la":"Oremus.","mark":"V"},{"k":"text","la":"Reminíscere miseratiónum tuárum, Dómine, et fámulos tuos ætérna protectióne sanctífica, pro quibus Christus, Fílius tuus, per suum cruórem instítuit paschále mystérium. Per eúndem Christum Dóminum nostrum. Amen."},{"k":"text","la":"Amen.","mark":"R"},{"k":"rubric","la":"36. Celebrans et ministri sacri de altari descendunt et, facta genuflexione, una cum acolythis, seu ministrantibus, in sacristiam revertuntur."},{"k":"ref","la":"37. In choro dicitur Completorium, candelis exstinctis, et absque cantu"},{"k":"rubric","la":"38. Tempore opportuno, sanctissima Eucharistia reportatur, forma simplici, ad locum reservationis, et ibidem asservatur, lampade de more accensa. Et denudatur altare."}]},"hr":{}});
